	"github.com/dolthub/dolt/go/store/chunks"
	"github.com/dolthub/dolt/go/store/hash"
	"github.com/dolthub/dolt/go/store/prolly"
	"github.com/dolthub/dolt/go/store/prolly/tree"
	"github.com/dolthub/dolt/go/store/types"
)

type database struct {
	*types.ValueStore
	rt rootTracker
	ns tree.NodeStore
}

var (
	ErrOptimisticLockFailed = errors.New("optimistic lock failed on database Root update")
	ErrMergeNeeded          = errors.New("dataset head is not ancestor of commit")
	ErrAlreadyCommitted     = errors.New("dataset head already pointing at given commit")
	ErrDirtyWorkspace       = errors.New("target has uncommitted changes. --force required to overwrite")
)

// rootTracker is a narrowing of the ChunkStore interface, to keep Database disciplined about working directly with Chunks
type rootTracker interface {
	Root(ctx context.Context) (hash.Hash, error)
	Commit(ctx context.Context, current, last hash.Hash) (bool, error)
}

func newDatabase(vs *types.ValueStore, ns tree.NodeStore) *database {
	return &database{
		ValueStore: vs, // ValueStore is responsible for closing |cs|
		rt:         vs,
		ns:         ns,
	}
}

var _ Database = &database{}
var _ GarbageCollector = &database{}

var _ rootTracker = &types.ValueStore{}
var _ GarbageCollector = &types.ValueStore{}

func (db *database) chunkStore() chunks.ChunkStore {
	return db.ChunkStore()
}

func (db *database) nodeStore() tree.NodeStore {
	return db.ns
}

func (db *database) Stats() interface{} {
	return db.ChunkStore().Stats()
}

func (db *database) StatsSummary() string {
	return db.ChunkStore().StatsSummary()
}

func (db *database) loadDatasetsRefmap(ctx context.Context, rootHash hash.Hash) (prolly.AddressMap, error) {
	if rootHash.IsEmpty() {
		return prolly.NewEmptyAddressMap(db.ns)
	}

type DoltDatabaseProvider struct {
	fs           filesys.Filesys
	remoteDialer dbfactory.GRPCDialProvider // TODO: why isn't this a method defined on the remote object

	// dbLoadParams are optional parameters to apply when loading local file-backed databases created
	// via provider-managed code paths (e.g. CREATE DATABASE / dolt_clone / undrop). These should match
	// the params threaded into env.DoltEnv.DBLoadParams by higher layers (e.g. engine.SqlEngineConfig.DBLoadParams).
	//
	// Note: these params are only effective if they are set before the underlying DoltDB is loaded.
	dbLoadParams map[string]interface{}

	// dbLocations maps a database name to its file system root
	dbLocations            map[string]filesys.Filesys
	databases              map[string]dsess.SqlDatabase
	functions              map[string]sql.Function
	tableFunctions         map[string]sql.TableFunction
	externalProcedures     sql.ExternalStoredProcedureRegistry
	isStandby              *bool
	mu                     *sync.RWMutex
	droppedDatabaseManager *droppedDatabaseManager
	overrides              sql.EngineOverrides

	// Databases named in deletingDatbases are currently undergoing deletion.
	// Databases with these names cannot created, but also return ErrNoDatabase
	// when accessed.
	deletingDatabases map[string]struct{}

	// creatingDatabases reserves names for clones fetching data from a remote.
	// CloneDatabaseFromRemote drops the provider lock for that network fetch, so
	// it records the name here to keep concurrent CREATE DATABASE / dolt_clone /
	// undrop of the same name serialized. Names are normalized with
	// formatDbMapKeyName, like p.databases (Dolt names are case-insensitive).
	//
	// Unlike deletingDatabases, this does not gate enumeration: enumeration only
	// ever reads the in-memory p.databases map at runtime, so an in-progress
	// clone's on-disk directory is simply invisible until it registers.
	creatingDatabases map[string]struct{}

	txLocks keymutex.Keymutex

	defaultBranch     string
	dbFactoryUrl      string
	DropDatabaseHooks []DropDatabaseHook
	InitDatabaseHooks []InitDatabaseHook
	gitRemotes        map[string]*doltdb.DoltDB
	gitRemotesMu      *sync.Mutex
}

// ProviderFactory creates a sql.DatabaseProvider for use as the engine's analyzer catalog
// provider.

type ValueReadWriter interface {
	ValueReader
	ValueWriter
}

// ValueStore provides methods to read and write Noms Values to a ChunkStore.
// It minimally validates Values as they're written, but does not guarantee
// that these Values are persisted through the ChunkStore until a subsequent
// Flush.
// Currently, WriteValue validates the following properties of a Value v:
// - v can be correctly serialized and its Ref taken
type ValueStore struct {
	cs                  chunks.ChunkStore
	decodedChunks       *sizecache.SizeCache
	nbf                 *NomsBinFormat
	gcCond              *sync.Cond
	gcNewAddrs          hash.HashSet
	gcState             gcState
	gcOut               int
	versOnce            sync.Once
	gcMu                sync.Mutex
	validateContentAddr bool
	skipWriteCaching    bool
}

type gcState int

const (
	gcState_NoGC   gcState = 0
	gcState_NewGen         = iota
